class ShoppingCart:
    ITEMS = 'items'
    PRICE = 'price'
    QUANTITY = 'quantity'

    def __init__(self):
        self._items = {}

    @property
    def items(self) -> dict:
        return self._items

    @items.setter
    def items(self, items: dict):
        self._items = items

    def _get_item(self, item) -> dict:
        return self._items.get(item)

    def _has_item(self, item) -> bool:
        return item in self._items

    def _set_item_item(self, item, item_dict):
        self._items[item] = item_dict

    def _get_item_price(self, item_dict) -> float:
        return item_dict[self.PRICE]

    def _get_item_quantity(self, item_dict) -> int:
        return item_dict[self.QUANTITY]

    def _set_item_quantity(self, item_dict, quantity):
        item_dict[self.QUANTITY] = quantity

    def add_item(self, item, price, quantity=1):
        if self._has_item(item):
            self._set_item_quantity(self._get_item(item), quantity)
        else:
            self._set_item_item(item, {self.PRICE: price, self.QUANTITY: quantity})

    def remove_item(self, item, quantity=1):
        item_dict = self._get_item(item)
        if item_dict is not None:
            new_quantity = self._get_item_quantity(item_dict) - quantity
            self._set_item_quantity(item_dict, new_quantity)

    def view_items(self) -> dict:
        return self._items

    def _item_line_total(self, item_dict) -> float:
        return self._get_item_quantity(item_dict) * self._get_item_price(item_dict)

    def total_price(self) -> float:
        return sum([self._item_line_total(item_dict) for item_dict in self._items.values()])
